use derive_setters :: Setters ; use forge_domain :: { Agent , AgentId , Compact , EventContext , MaxTokens , ModelId , ProviderId , ReasoningConfig , SystemContext , Temperature , Template , ToolName , TopK , TopP , } ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; # [doc = " Agent definition - used for deserialization from configuration files."] # [doc = " Fields like model and provider are optional to support defaults."] # [doc = " This type is a repo concern: it models how agents are stored on disk and"] # [doc = " is converted to the domain [`Agent`] type before use."] # [derive (Debug , Clone , Serialize , Deserialize , Setters , JsonSchema)] # [setters (strip_option , into)] # [serde (rename = "Agent")] pub (crate) struct AgentDefinition { # [doc = " Flag to enable/disable tool support for this agent."] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub tool_supported : Option < bool > , pub id : AgentId , # [doc = " Path to the agent definition file, if loaded from a file"] # [serde (skip)] pub path : Option < String > , # [doc = " Human-readable title for the agent"] # [serde (skip_serializing_if = "Option::is_none")] pub title : Option < String > , # [serde (skip_serializing_if = "Option::is_none")] pub provider : Option < ProviderId > , # [serde (default , skip_serializing_if = "Option::is_none")] pub model : Option < ModelId > , # [serde (default , skip_serializing_if = "Option::is_none")] pub description : Option < String > , # [serde (default , skip_serializing_if = "Option::is_none")] pub system_prompt : Option < Template < SystemContext > > , # [serde (default , skip_serializing_if = "Option::is_none")] pub user_prompt : Option < Template < EventContext > > , # [doc = " Tools that the agent can use"] # [serde (default , skip_serializing_if = "Option::is_none")] pub tools : Option < Vec < ToolName > > , # [doc = " Maximum number of turns the agent can take"] # [serde (default , skip_serializing_if = "Option::is_none")] pub max_turns : Option < u64 > , # [doc = " Configuration for automatic context compaction"] # [serde (default , skip_serializing_if = "Option::is_none")] pub compact : Option < Compact > , # [doc = " A set of custom rules that the agent should follow"] # [serde (default , skip_serializing_if = "Option::is_none")] pub custom_rules : Option < String > , # [doc = " Temperature used for agent"] # [doc = ""] # [doc = " Temperature controls the randomness in the model's output."] # [doc = " - Lower values (e.g., 0.1) make responses more focused, deterministic,"] # [doc = "   and coherent"] # [doc = " - Higher values (e.g., 0.8) make responses more creative, diverse, and"] # [doc = "   exploratory"] # [doc = " - Valid range is 0.0 to 2.0"] # [doc = " - If not specified, the model provider's default temperature will be"] # [doc = "   used"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub temperature : Option < Temperature > , # [doc = " Top-p (nucleus sampling) used for agent"] # [doc = ""] # [doc = " Controls the diversity of the model's output by considering only the"] # [doc = " most probable tokens up to a cumulative probability threshold."] # [doc = " - Lower values (e.g., 0.1) make responses more focused"] # [doc = " - Higher values (e.g., 0.9) make responses more diverse"] # [doc = " - Valid range is 0.0 to 1.0"] # [doc = " - If not specified, the model provider's default will be used"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub top_p : Option < TopP > , # [doc = " Top-k used for agent"] # [doc = ""] # [doc = " Controls the number of highest probability vocabulary tokens to keep."] # [doc = " - Lower values (e.g., 10) make responses more focused"] # [doc = " - Higher values (e.g., 100) make responses more diverse"] # [doc = " - Valid range is 1 to 1000"] # [doc = " - If not specified, the model provider's default will be used"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub top_k : Option < TopK > , # [doc = " Maximum number of tokens the model can generate"] # [doc = ""] # [doc = " Controls the maximum length of the model's response."] # [doc = " - Lower values (e.g., 100) limit response length for concise outputs"] # [doc = " - Higher values (e.g., 4000) allow for longer, more detailed responses"] # [doc = " - Valid range is 1 to 100,000"] # [doc = " - If not specified, the model provider's default will be used"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub max_tokens : Option < MaxTokens > , # [doc = " Reasoning configuration for the agent."] # [doc = " Controls the reasoning capabilities of the agent"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub reasoning : Option < ReasoningConfig > , # [doc = " Maximum number of times a tool can fail before sending the response back"] # [doc = " to the LLM forces the completion."] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub max_tool_failure_per_turn : Option < usize > , # [doc = " Maximum number of requests that can be made in a single turn"] # [serde (default)] # [serde (skip_serializing_if = "Option::is_none")] pub max_requests_per_turn : Option < usize > , }